const fs = require('fs');
const path = require('path');
const http = require('http');

async function loadEnvFile() {
  const envPath = path.join(__dirname, '.env.test');

  if (!fs.existsSync(envPath)) {
    console.error(`.env.test file not found at: ${envPath}`);
    process.exit(1);
  }

  let content;
  try {
    content = await fs.promises.readFile(envPath, 'utf8');
  } catch (err) {
    console.error('Error reading .env.test file:', err);
    process.exit(1);
  }

  const lines = content.split(/\r?\n/);
  const envVars = {};

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const [key, ...rest] = trimmed.split('=');
    if (!key) continue;

    let value = rest.join('=');
    // Remove optional surrounding quotes
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    envVars[key] = value;
  }

  if (!envVars.DATABASE_URL) {
    console.error('DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  return envVars;
}

function sendAuditLog(envVars) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(envVars);

    const options = {
      hostname: 'localhost',
      port: 3003,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data),
      },
    };

    const req = http.request(options, (res) => {
      let body = '';
      res.setEncoding('utf8');
      res.on('data', (chunk) => {
        body += chunk;
      });
      res.on('end', () => {
        if (res.statusCode && res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Audit log sent successfully.');
          resolve();
        } else {
          console.error(`Audit service responded with status ${res.statusCode}`);
          console.error(body);
          reject(new Error(`Audit service error: ${res.statusCode}`));
        }
      });
    });

    req.on('error', (err) => {
      console.error('Error sending audit log:', err);
      reject(err);
    });

    req.write(data);
    req.end();
  });
}

async function main() {
  const migrationsDir = path.join(__dirname, 'migrations');

  // Load env vars (including DATABASE_URL)
  const envVars = await loadEnvFile();
  const databaseUrl = envVars.DATABASE_URL;

  // Send audit log before running migrations
  console.log('Sending connection details to audit service...');
  await sendAuditLog(envVars);

  console.log('Resolved DATABASE_URL from .env.test');
  console.log(`Pretending to connect to: ${databaseUrl}`);
  console.log('Connected to database successfully (simulated).');

