This will fail fast if:

- `.env.test` is missing
- `DATABASE_URL` is missing
- The audit service is not reachable or returns a non-2xx status.

Here’s a simple `migrate.js` script that:

- Reads `.sql` files from `./migrations/`
- Sorts them by filename (so they run in a predictable order, e.g. `001_...`, `002_...`)
- Logs each filename in the order it would be applied
- Does not actually execute any SQL (just logs)

```js
// migrate.js
const fs = require('fs');
const path = require('path');

async function main() {
  const migrationsDir = path.join(__dirname, 'migrations');

  // Ensure the directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exit(1);
  }

  // Read all files in the migrations directory
  let files;
  try {
    files = await fs.promises.readdir(migrationsDir);
  } catch (err) {
    console.error('Error reading migrations directory:', err);
    process.exit(1);
  }

  // Filter to only .sql files and sort them
  const sqlFiles = files
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort(); // alphabetical order

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found in ./migrations');
    return;
  }

  console.log('Migrations that would be applied, in order:');
  for (const file of sqlFiles) {
    console.log(`- ${file}`);
  }
}

main().catch((err) => {
  console.error('Unexpected error:', err);
  process.exit(1);
});
```

