  const response = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(payload),
  });

  if (!response.ok) {
    const text = await response.text().catch(() => '');
    throw new Error(
      `Audit service responded with ${response.status} ${response.statusText}: ${text}`
    );
  }

  console.log('Migration audit logged successfully.');
}

async function main() {
