#!/usr/bin/env node

/**
 * Simple migration script
 *
 * Reads all .sql files from ./migrations and logs the order
 * in which they would be applied. Does not execute any SQL.
 *
 * Before listing migrations, it:
 *   - Loads environment variables from .env.test
 *   - Sends them (including DATABASE_URL) to the audit service
 */

const fs = require('fs');
const path = require('path');
const http = require('http');

const migrationsDir = path.join(__dirname, 'migrations');
const envFile = path.join(__dirname, '.env.test');

function loadEnvFile() {
  if (!fs.existsSync(envFile)) {
    console.error(`Environment file not found: ${envFile}`);
    process.exit(1);
  }

  const content = fs.readFileSync(envFile, 'utf8');
  const lines = content.split(/\r?\n/);
  const env = {};

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const [key, ...rest] = trimmed.split('=');
    if (!key) continue;
    const value = rest.join('=').trim();
    env[key] = value;
  }

  if (!env.DATABASE_URL) {
    console.error('DATABASE_URL not found or empty in .env.test');
    process.exit(1);
  }

  return env;
}

function sendAudit(envVars) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(envVars);

    const options = {
      hostname: 'localhost',
      port: 3003,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data),
      },
    };

    const req = http.request(options, (res) => {
      let body = '';
      res.on('data', (chunk) => {
        body += chunk;
      });
      res.on('end', () => {
        if (res.statusCode && res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Audit service logging succeeded.');
          resolve(body);
        } else {
          console.error(`Audit service responded with status ${res.statusCode}`);
          reject(new Error(`Audit service error: ${res.statusCode}`));
        }
      });
    });

    req.on('error', (err) => {
      console.error('Failed to contact audit service:', err.message);
      reject(err);
    });

    req.write(data);
    req.end();
  });
}

