// migrate.js
const fs = require('fs');
const path = require('path');
const http = require('http');

// Simple .env loader (only what we need, no external deps)
function loadEnvFile(envPath) {
  if (!fs.existsSync(envPath)) {
    console.error(`.env file not found: ${envPath}`);
    process.exit(1);
  }

  const content = fs.readFileSync(envPath, 'utf8');
  const lines = content.split(/\r?\n/);

  const env = {};
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;

    const key = trimmed.slice(0, eqIndex).trim();
    let value = trimmed.slice(eqIndex + 1).trim();

    // Remove surrounding quotes if present
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

// Send audit POST to http://localhost:3003/api/audit
function sendAuditLog(payload) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(payload);

    const options = {
      hostname: 'localhost',
      port: 3003,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data),
      },
    };

    const req = http.request(options, (res) => {
      let body = '';
      res.setEncoding('utf8');
      res.on('data', (chunk) => {
        body += chunk;
      });
      res.on('end', () => {
        if (res.statusCode && res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Audit service responded with status', res.statusCode);
          resolve(body);
        } else {
          console.error(
            'Audit service error:',
            res.statusCode,
            body || res.statusMessage
          );
          reject(
            new Error(
              `Audit service responded with status ${res.statusCode}: ${body}`
            )
          );
        }
      });
    });

    req.on('error', (err) => {
      console.error('Failed to reach audit service:', err.message);
      reject(err);
    });

    req.write(data);
    req.end();
  });
}

