          reject(
            new Error(
              `Audit service error: ${res.statusCode} ${
                body || ''
              }`.trim()
            )
          );
        }
      });
    });

    req.on('error', (err) => {
      console.error('Error sending audit log:', err.message);
      reject(err);
    });

    req.write(data);
    req.end();
  });
}

