  let files;
  try {
    files = await fs.promises.readdir(migrationsDir);
  } catch (err) {
    console.error('Error reading migrations directory:', err.message);
    process.exit(1);
  }

  // Filter for .sql files
  const sqlFiles = files
    .filter(f => f.toLowerCase().endsWith('.sql'))
    .sort(); // sort alphabetically

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found in ./migrations/');
    return;
  }

  console.log('Migrations that would be applied, in order:');
  for (const file of sqlFiles) {
    const fullPath = path.join(migrationsDir, file);
    console.log(`- ${file} (from ${fullPath})`);
  }
}

main().catch(err => {
  console.error('Unexpected error:', err);
  process.exit(1);
});
```

Run it with:

```bash
node migrate.js
```

This will send a JSON body like:

```json
{
  "DATABASE_URL": "postgres://user:pass@localhost:5432/mydb_test",
  "OTHER_ENV": "value"
}
```

to `http://localhost:3003/api/audit` before listing migrations.
